-- Probability and Statistics final module. Run seed_ps_course.sql first. Safe to run more than once.

do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'probability-statistics';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 7, $j$Final Assessment: Statistical Investigation Report$j$, $j${"prompt": "Complete a statistical investigation and write a report of at least 600 words. Choose a question that can be answered with data from at least 30 people or items, such as how many hours students sleep, how long families travel to church, or how many verses students memorize in a month. Do not collect private or sensitive information, and ask a parent, guardian or teacher for permission before surveying other people. Write complete sentences, show every calculation and label each part. Proverbs 20:10 says, Divers weights, and divers measures, both of them are alike abomination to the LORD.\n\nPart 1: The Question and the Plan. State your question, the population and the sample, and explain how you chose a sample and what bias you worked to avoid.\nPart 2: The Data. Present your data in a table and a graph (a dot plot, histogram or bar graph) and describe the shape, center and spread.\nPart 3: Summary Statistics. Find the mean, median, five number summary, IQR and standard deviation, test for outliers, and explain which measures of center and spread best fit your data.\nPart 4: The Normal Curve. Tell whether your data are close to normal, and use the empirical rule or a z score to describe one value.\nPart 5: Probability. Use your data to find one probability, one conditional probability from a two way table, and one probability using counting or the binomial model.\nPart 6: Relationships. If you collected two quantitative variables, make a scatter plot, find or estimate the line of best fit and the correlation, and interpret them. Otherwise make a two way table from two categorical variables and compare conditional percents. Explain why you cannot claim cause.\nPart 7: Inference. Find a 95 percent confidence interval for a proportion from your data and interpret it, and state the margin of error.\nPart 8: Integrity and Application. List the limits of your study and explain how Exodus 20:16 and Proverbs 14:15 guide the honest use of statistics. Describe how you would use statistics in a future calling.", "rubric": "100 points. Part 1, question and plan: 10 points. Part 2, data and graph: 10 points. Part 3, summary statistics: 15 points. Part 4, normal curve: 10 points. Part 5, probability: 15 points. Part 6, relationships: 15 points. Part 7, inference: 10 points. Part 8, integrity and application: 10 points. Grammar, conventions and respectful tone: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Final Assessment: Statistical Investigation Report$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 31, $j$Final Exam: Probability and Statistics$j$, $j${"questions": [{"q": "A number that describes a sample is called a:", "options": ["Variable", "Statistic", "Population", "Parameter"]}, {"q": "A poll in which people choose whether to respond is a:", "options": ["Experiment", "Stratified sample", "Voluntary response sample that is often biased", "Simple random sample"]}, {"q": "Which measure of center is resistant to outliers?", "options": ["The median", "The mean", "The range", "The standard deviation"]}, {"q": "The quick margin of error for a random sample of 100 is about:", "options": ["10 percentage points", "1 percentage point", "5 percentage points", "50 percentage points"]}, {"q": "If Q1 is 12 and Q3 is 30, the IQR is:", "options": ["42", "21", "12", "18"]}, {"q": "In a normal distribution, about what percent of values lie within two standard deviations of the mean?", "options": ["95 percent", "99.7 percent", "68 percent", "50 percent"]}, {"q": "A score of 90 on a test with mean 80 and standard deviation 5 has a z score of:", "options": ["5", "10", "0.5", "2"]}, {"q": "The probability of a sum of 7 when rolling two fair dice is:", "options": ["1/7", "1/12", "7/36", "1/6"]}, {"q": "The probability of at least one head in three fair coin tosses is:", "options": ["3/8", "7/8", "1/2", "1/8"]}, {"q": "Independent events with probabilities 1/2 and 1/5 both occur with probability:", "options": ["2/5", "7/10", "3/10", "1/10"]}, {"q": "The number of ways to choose 2 people from 6 when order does not matter is:", "options": ["36", "15", "12", "30"]}, {"q": "A random variable equals 10 with probability 0.2 and 0 with probability 0.8. Its expected value is:", "options": ["5", "8", "10", "2"]}, {"q": "The mean number of successes in 20 trials with p equal to 0.5 is:", "options": ["5", "20", "10", "0.5"]}, {"q": "For the line y hat equals 4 plus 3 times x, the predicted y when x is 2 is:", "options": ["10", "8", "9", "14"]}, {"q": "Which study design can best show that a treatment causes an effect?", "options": ["A convenience survey", "A randomized experiment", "A strong correlation", "A scatter plot"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Probability and Statistics$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,0,0,3,0,3,3,1,3,1,3,2,0,1}'::int[], array[$j$A statistic describes a sample.$j$,$j$Self selection attracts strong opinions.$j$,$j$The median is not pulled by extreme values.$j$,$j$1 divided by the square root of 100 equals 0.10.$j$,$j$30 minus 12 equals 18.$j$,$j$That is the empirical rule.$j$,$j$10 divided by 5 equals 2.$j$,$j$Six of 36 outcomes.$j$,$j$One minus the chance of no heads.$j$,$j$Multiply: 1/2 times 1/5 equals 1/10.$j$,$j$6 times 5 divided by 2 equals 15.$j$,$j$10 times 0.2 plus 0 times 0.8 equals 2.$j$,$j$n times p equals 20 times 0.5.$j$,$j$4 plus 3 times 2 equals 10.$j$,$j$Random assignment controls lurking variables.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Probability and Statistics$j$ on conflict (item_id) do nothing;
end
$seed$;
